// Source model/input preparation only, outside all primary training timings.
#include <pthread.h>
#include "corrected_native/src/sgd.cu"
#include <fstream>
#include <cstdint>
#include <vector>
template<class T>void put(std::ofstream&f,const T*p,size_t n){f.write((const char*)p,n*sizeof(T));if(!f)throw std::runtime_error("fixture write");}
int main(int argc,char**argv){if(argc!=4)return 2;mf_problem prob=read_problem(argv[1]);prob.u_grid=prob.v_grid=prob.x_grid=prob.y_grid=prob.ux=prob.vy=1;float ave,stddev;collect_data(&prob,ave,stddev);float scale=std::max(1e-4f,stddev);int *pm=gen_random_map(prob.m),*qm=gen_random_map(prob.n),*ip=gen_inv_map(pm,prob.m),*iq=gen_inv_map(qm,prob.n);shuffle_problem(&prob,pm,qm);grid_problem(&prob);scale_problem(&prob,1.f/scale,prob.u_seg,prob.v_seg);mf_model*model=init_model(&prob,128,ave/stddev);mf_problem test=read_problem(argv[2]);std::ofstream f(argv[3],std::ios::binary);uint32_t magic[]={0x4d465331U,1};put(f,magic,2);int32_t h[]={prob.m,prob.n,128,34};put(f,h,4);int64_t counts[]={prob.nnz,test.nnz};put(f,counts,2);float parameters[]={scale,ave,stddev,model->b,.01f,.01f,0.f,.05f/scale,.05f/scale};put(f,parameters,9);put(f,pm,prob.m);put(f,qm,prob.n);put(f,ip,prob.m);put(f,iq,prob.n);put(f,prob.R,prob.nnz);put(f,test.R,test.nnz);put(f,model->halfp,size_t(prob.m)*128);put(f,model->halfq,size_t(prob.n)*128);float rates[34];for(int i=0;i<34;i++)rates[i]=parameters[4]/(1+parameters[5]*pow(i,1.5))+parameters[6];put(f,rates,34);f.close();std::ifstream input(argv[3],std::ios::binary|std::ios::ate);size_t bytes=input.tellg();printf("SOURCE_INPUT_PREPARATION {\"m\":%d,\"n\":%d,\"k\":128,\"train\":%lld,\"test\":%lld,\"scale\":%.9g,\"training_kernel_executed\":false}\n",prob.m,prob.n,prob.nnz,test.nnz,scale);printf("STUDY_TRIAL {\"trial\":1,\"correct\":true,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"timing_region\":\"input_preparation_only_no_training_or_performance_measurement\",\"jit_excluded\":false,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint8\",\"count\":%zu,\"byte_order\":\"little\"}}\n",bytes,argv[3],bytes);cudaFreeHost(model->floatp);cudaFreeHost(model->floatq);cudaFreeHost(model->halfp);cudaFreeHost(model->halfq);cudaFreeHost(prob.R);cudaFreeHost(test.R);return 0;}
